mapper.select:
SELECT COUNT(*) FROM ( SELECT arrange_id,arrange_code,task_code,produce_task_code,tenant_id,factory_code,del_flag,start_time,end_time, CAST(NULL AS varchar) AS identifier,CAST(NULL AS varchar) AS identifier_type FROM mom_mes.mes_task_execution_segment UNION ALL SELECT arrange_id,arrange_code,task_code,produce_task_code,tenant_id,factory_code,del_flag,labor_start,labor_end, CAST(NULL AS varchar) AS identifier,CAST(NULL AS varchar) AS identifier_type FROM mom_mes.mes_labor_entry WHERE status IN ('APPROVED','VOID_PENDING') UNION ALL SELECT arrange_id,arrange_code,task_code,produce_task_code,tenant_id,factory_code,del_flag,start_time,end_time,identifier,identifier_type FROM mom_mes.mes_workpiece_time_interval WHERE status IN ('OPEN','CLOSED') UNION ALL
SELECT e.arrange_id,e.arrange_code,e.task_code,e.produce_task_code,e.tenant_id,e.factory_code,e.del_flag, e.event_time,e.next_time,CAST(NULL AS varchar),CAST(NULL AS varchar) FROM ( SELECT timing.*,LEAD(timing.event_time) OVER ( PARTITION BY timing.arrange_id ORDER BY timing.event_version ) AS next_time FROM mom_mes.mes_arrange_timing_event timing WHERE timing.tenant_id=#{tenant} AND timing.factory_code=#{factory} AND timing.del_flag='0' ) e WHERE e.status='PAUSE' ) source WHERE source.tenant_id=#{tenant} AND source.factory_code=#{factory} AND source.del_flag='0' AND (source.start_time < #{q.endTime} OR source.start_time IS NULL) AND (source.end_time > #{q.startTime} OR source.end_time IS NULL OR source.end_time < source.start_time OR (source.end_time=source.start_time AND source.start_time >= #{q.startTime})) AND source.task_code=#{q.taskCode} AND source.produce_task_code=#{q.produceTaskCode} AND source.arrange_code=#{q.arrangeCode}
AND source.identifier=#{q.identifier} AND source.identifier_type=#{q.identifierType}
AND NOT EXISTS (SELECT 1 FROM mom_mes.mes_task_arrange a WHERE a.id=source.arrange_id AND a.code=source.arrange_code AND a.task_code=source.task_code AND a.produce_task_code=source.produce_task_code AND a.tenant_id=source.tenant_id AND a.factory_code=source.factory_code AND a.del_flag='0')

