mapper.select:
SELECT 'WORKPIECE_TIME' AS source_type,CAST(w.id AS varchar) AS source_id, w.task_code,w.produce_task_code,w.arrange_code,a.workshop_code,a.shift_code, w.device_code,w.worker_code,w.identifier,w.identifier_type, CASE WHEN w.kind='RUN' THEN 'WORKPIECE_RUN' WHEN w.kind='PAUSE' THEN 'WORKPIECE_PAUSE' ELSE 'UNKNOWN' END AS kind, w.start_time,w.end_time,w.status AS state,TRUE AS eligible,w.reason_code AS reason FROM mom_mes.mes_workpiece_time_interval w JOIN mom_mes.mes_task_arrange a ON a.id=w.arrange_id AND a.code=w.arrange_code AND a.task_code=w.task_code AND a.produce_task_code=w.produce_task_code AND a.tenant_id=w.tenant_id AND a.factory_code=w.factory_code WHERE w.tenant_id=#{tenant} AND w.factory_code=#{factory} AND w.del_flag='0' AND w.status IN ('OPEN','CLOSED') AND w.start_time < #{q.endTime} AND (w.end_time > #{q.startTime} OR w.end_time IS NULL OR w.end_time < w.start_time OR (w.end_time=w.start_time AND w.start_time >= #{q.startTime}))
AND w.identifier=#{q.identifier} AND w.identifier_type=#{q.identifierType}
AND ORDER BY w.id LIMIT #{limit}
